package contract

import (
	"path/filepath"
	"slices"
	"strings"
)

var Languages = []Language{PHP, Vue, TypeScript, Python, CSharp, Go}

// facts is what the tool knows of a language besides parsing it, stated once for every package that needs it: its
// file extensions, the name a reader sees, how a line comment is written and opened, and how a generated file is told.
type facts struct {
	extensions        []string
	label             string
	comment           [2]string
	commentOpeners    []string
	generatedNames    []string
	generatedHeadings []string
}

var described = map[Language]facts{
	PHP:        {extensions: []string{"php"}, label: "PHP", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"}},
	Vue:        {extensions: []string{"vue"}, label: "Vue", comment: [2]string{"<!-- ", " -->"}, commentOpeners: []string{"<!--"}},
	TypeScript: {extensions: []string{"ts", "tsx", "mts", "cts", "js", "jsx", "mjs", "cjs"}, label: "TypeScript", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"}},
	Python:     {extensions: []string{"py"}, label: "Python", comment: [2]string{"# ", ""}, commentOpeners: []string{"#"}},
	CSharp: {extensions: []string{"cs"}, label: "C#", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"},
		generatedNames: []string{".g.cs", ".g.i.cs", ".designer.cs", ".generated.cs"}, generatedHeadings: []string{"<auto-generated", "<autogenerated"}},
	Go: {extensions: []string{"go"}, label: "Go", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"}},
}

// Label is the language's name as a reader sees it.
func Label(language Language) string {
	return described[language].label
}

// CommentOf is the text written as a line comment of the language.
func CommentOf(language Language, text string) string {
	return described[language].comment[0] + text + described[language].comment[1]
}

// IsCommentLine says whether the line opens with a comment of the language.
func IsCommentLine(language Language, line string) bool {
	opened := strings.TrimLeft(line, " \t\n\r\x00\x0B")

	return slices.ContainsFunc(described[language].commentOpeners, func(opener string) bool { return strings.HasPrefix(opened, opener) })
}

// IsGenerated says whether a file of the language is one a tool wrote: by its name, or by what its opening comments say.
func IsGenerated(language Language, path, heading string) bool {
	name, heading := strings.ToLower(filepath.Base(path)), strings.ToLower(heading)

	return slices.ContainsFunc(described[language].generatedNames, func(suffix string) bool { return strings.HasSuffix(name, suffix) }) ||
		slices.ContainsFunc(described[language].generatedHeadings, func(mark string) bool { return strings.Contains(heading, mark) })
}

func ExtensionsOf(language Language) []string {
	return described[language].extensions
}

func LanguageOfPath(path string) (Language, bool) {
	extension := strings.ToLower(strings.TrimPrefix(filepath.Ext(path), "."))
	for _, language := range Languages {
		if slices.Contains(described[language].extensions, extension) {
			return language, true
		}
	}

	return "", false
}
